// TTOken Code issues board reads. Generated by ttoken/apply-brand.mjs from ttoken/forge/issues.spec.ts; edit it there.
import { describe, expect, it } from 'vitest'
import type { GhOutput, GhRunner } from '../src/gh.ts'
import { GitHubProvider } from '../src/provider.ts'
import type { GitHubLimits } from '../src/provider.ts'
import { demo } from './fixtures.ts'

const signal = new AbortController().signal

const limits: GitHubLimits = {
  maxOutputBytes: 8_388_608, maxReviewThreads: 1_000, maxCommits: 250, maxViewedFiles: 3_000, maxViewerItems: 50,
}

function fakeGh(handler: (args: readonly string[]) => GhOutput): { run: GhRunner; calls: string[][] } {
  const calls: string[][] = []
  return { calls, run: async (args) => { calls.push([...args]); return handler(args) } }
}

function output(stdout: unknown): GhOutput {
  return { exitCode: 0, stdout: JSON.stringify(stdout), stderr: '' }
}

function pullNode(number: number, state: string, rollup: string | null | undefined, isDraft = false): Record<string, unknown> {
  const nodes = rollup === undefined ? [] : [{ commit: { statusCheckRollup: rollup === null ? null : { state: rollup } } }]
  return { number, url: `https://github.com/octo/demo/pull/${number}`, state, isDraft, commits: { nodes } }
}

function issueNode(number: number, overrides: Record<string, unknown> = {}): Record<string, unknown> {
  return {
    number,
    title: `Issue ${number}`,
    url: `https://github.com/octo/demo/issues/${number}`,
    state: 'OPEN',
    body: 'Steps to reproduce',
    updatedAt: '2026-11-18T10:00:00Z',
    author: { login: 'octocat' },
    assignees: { nodes: [{ login: 'hubot' }] },
    labels: { nodes: [{ name: 'bug', color: 'd73a4a' }] },
    comments: { totalCount: 2 },
    closedByPullRequestsReferences: { nodes: [] },
    ...overrides,
  }
}

function board(open: unknown[], closed: unknown[], viewer: unknown = { login: 'octocat' }): Record<string, unknown> {
  return { data: { viewer, repository: { open: { totalCount: open.length + 3, nodes: open }, closed: { nodes: closed } } } }
}

describe('GitHub issues board', () => {
  it('reads open and closed issues with their labels, assignees, and closing pull requests and checks', async () => {
    const gh = fakeGh(() => output(board([
      issueNode(7, {
        closedByPullRequestsReferences: {
          nodes: [
            pullNode(11, 'OPEN', 'SUCCESS'),
            pullNode(12, 'OPEN', 'ERROR', true),
            pullNode(13, 'CLOSED', 'EXPECTED'),
            pullNode(14, 'OPEN', null),
            pullNode(15, 'OPEN', undefined),
          ],
        },
      }),
    ], [
      issueNode(3, { state: 'CLOSED', author: null, closedByPullRequestsReferences: { nodes: [pullNode(9, 'MERGED', 'FAILURE')] } }),
    ])))
    const result = await new GitHubProvider(gh.run, ['github.com'], limits).listIssues(demo, signal)
    expect(result).toEqual({
      open: [{
        number: 7,
        title: 'Issue 7',
        url: 'https://github.com/octo/demo/issues/7',
        state: 'open',
        body: 'Steps to reproduce',
        author: 'octocat',
        assignees: ['hubot'],
        labels: [{ name: 'bug', color: 'd73a4a' }],
        comments: 2,
        updatedAt: '2026-11-18T10:00:00Z',
        pullRequests: [
          { number: 11, url: 'https://github.com/octo/demo/pull/11', state: 'open', draft: false, checks: 'success' },
          { number: 12, url: 'https://github.com/octo/demo/pull/12', state: 'open', draft: true, checks: 'failure' },
          { number: 13, url: 'https://github.com/octo/demo/pull/13', state: 'closed', draft: false, checks: 'pending' },
          { number: 14, url: 'https://github.com/octo/demo/pull/14', state: 'open', draft: false, checks: null },
          { number: 15, url: 'https://github.com/octo/demo/pull/15', state: 'open', draft: false, checks: null },
        ],
      }],
      closed: [expect.objectContaining({
        number: 3,
        state: 'closed',
        author: null,
        pullRequests: [{ number: 9, url: 'https://github.com/octo/demo/pull/9', state: 'merged', draft: false, checks: 'failure' }],
      })],
      openTotal: 4,
      viewer: 'octocat',
    })
    expect(gh.calls).toEqual([[
      'api', 'graphql', '--hostname', 'github.com', '-f', expect.stringContaining('fragment BoardIssue on Issue'),
      '-f', 'owner=octo', '-f', 'name=demo', '-F', 'open=50', '-F', 'closed=10',
    ]])
  })

  it('cuts a long body and leaves out an issue node GitHub shapes differently', async () => {
    const gh = fakeGh(() => output(board([issueNode(1, { body: 'x'.repeat(4_100) }), { number: 2 }], [], null)))
    const result = await new GitHubProvider(gh.run, ['github.com'], limits).listIssues(demo, signal)
    if ('code' in result) throw new Error(result.message)
    expect(result.open.map(issue => issue.number)).toEqual([1])
    expect(result.open[0]?.body).toBe(`${'x'.repeat(4_000)}…`)
    expect(result.viewer).toBeNull()
  })

  it('reports a missing repository as not found and another response as unavailable', async () => {
    const missing = fakeGh(() => output({ data: { viewer: { login: 'octocat' }, repository: null } }))
    expect(await new GitHubProvider(missing.run, ['github.com'], limits).listIssues(demo, signal))
      .toEqual({ code: 'not-found', message: 'GitHub has no repository octo/demo' })
    const odd = fakeGh(() => output({ data: { repository: { open: [] } } }))
    expect(await new GitHubProvider(odd.run, ['github.com'], limits).listIssues(demo, signal))
      .toEqual({ code: 'unavailable', message: 'unexpected GitHub response to the issue list' })
  })

  it('refuses a host the provider does not serve without running gh', async () => {
    const gh = fakeGh(() => output(board([], [])))
    const result = await new GitHubProvider(gh.run, ['github.com'], limits).listIssues({ ...demo, host: 'git.example.com' }, signal)
    expect(result).toMatchObject({ code: 'unavailable' })
    expect(gh.calls).toEqual([])
  })
})
